package com.gymmind.membership.application;
import com.gymmind.audit.application.AuditRecorder; import com.gymmind.iam.domain.model.RoleCode; import com.gymmind.membership.domain.model.PaymentRecord; import com.gymmind.membership.domain.repository.PaymentRecordRepository; import com.gymmind.membership.domain.repository.OrderRepository; import com.gymmind.shared.security.CurrentActor; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.util.Optional; import java.util.Set; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
class PaymentRecordServiceTest { @Test void offlinePaymentIsIdempotentByReference(){PaymentRecordRepository payments=mock(PaymentRecordRepository.class); OrderRepository orders=mock(OrderRepository.class); when(payments.findByTenantIdAndReference(11L,"R-1")).thenReturn(Optional.empty()); when(payments.save(any(PaymentRecord.class))).thenAnswer(i->i.getArgument(0)); DefaultPaymentRecordService service=new DefaultPaymentRecordService(payments,orders,mock(AuditRecorder.class)); PaymentRecordView v=service.recordOfflinePayment(admin(11L),new RecordOfflinePaymentCommand(null,8L,new BigDecimal("99.00"),"CNY","R-1","CASH")); assertThat(v.reference()).isEqualTo("R-1"); verify(payments).save(any(PaymentRecord.class)); when(payments.findByTenantIdAndReference(11L,"R-1")).thenReturn(Optional.of(PaymentRecord.create(11L,8L,new BigDecimal("99.00"),"CNY","R-1","CASH"))); assertThat(service.recordOfflinePayment(admin(11L),new RecordOfflinePaymentCommand(null,8L,new BigDecimal("99.00"),"CNY","R-1","CASH")).reference()).isEqualTo("R-1"); } private static CurrentActor admin(long t){return new CurrentActor(1L,t,Set.of(RoleCode.GYM_ADMIN),Set.of("payment:write"),0L,"token");}}
